import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SetLocalPlayerAsInitialised{EntityRuntimeID: 300}
NARROW = bytes.fromhex("ac02")

# generated by gophertunnel b8bd735:
# &packet.SetLocalPlayerAsInitialised{EntityRuntimeID: 4294967303}
WIDE = bytes.fromhex("8780808010")

GOLDENS = [
    pytest.param(v2225.SetLocalPlayerAsInitializedPacket(player_id=300), NARROW, id="narrow"),
    pytest.param(v2225.SetLocalPlayerAsInitializedPacket(player_id=4294967303), WIDE, id="id-is-a-64-bit-varint"),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_set_local_player_as_initialized_is_packet_113(version):
    assert version.PACKETS[113] is version.SetLocalPlayerAsInitializedPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_local_player_as_initialized_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_local_player_as_initialized_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
